{
  "name": "电力路由软件组件",
  "name_en": "Power Routing Software Component",
  "manufacturer": "",
  "description": "非物理软件组件，用于在实验或设施能源管理场景中统一表示可参与电力调度的对象。它提供配置加载、运行与停止、功率查询、可释放功率计算、功率占用以及状态发布等接口，可被智能插座、电池或充电控制对象等上层模块复用。",
  "description_en": "A non-physical software component used to represent objects that can participate in power scheduling in laboratory or facility energy-management scenarios. It provides interfaces for loading configuration, running and stopping, querying power, calculating releasable power, taking power, and publishing status, and can be reused by higher-level modules such as smart plugs, batteries, or EVSE control objects.",
  "tag_hints": [
    "power routing",
    "energy management",
    "power allocation",
    "smart plug integration",
    "battery coordination",
    "EVSE control",
    "non-physical control module"
  ],
  "actions": [
    {
      "action_name": "auto-load_config",
      "description": "加载路由配置。",
      "description_en": "Load routing configuration."
    },
    {
      "action_name": "auto-stop",
      "description": "停止该电力路由组件。",
      "description_en": "Stop the power routing component."
    },
    {
      "action_name": "auto-dump",
      "description": "导出当前路由状态或配置。",
      "description_en": "Dump the current routing state or configuration."
    },
    {
      "action_name": "auto-run",
      "description": "运行电力路由逻辑。",
      "description_en": "Run the power routing logic."
    },
    {
      "action_name": "auto-get_power",
      "description": "获取当前功率值。",
      "description_en": "Get the current power value."
    },
    {
      "action_name": "auto-get_releaseable_power",
      "description": "获取给定上下文中可释放的功率。",
      "description_en": "Get the releasable power in the given context."
    },
    {
      "action_name": "auto-take_power",
      "description": "在给定上下文中占用或分配功率。",
      "description_en": "Take or allocate power in the given context."
    },
    {
      "action_name": "auto-publish",
      "description": "发布当前状态或功率信息。",
      "description_en": "Publish the current status or power information."
    }
  ]
}

